          refine' ⟨ { ⟨ ( Real.sqrt ( q3 j ) : ℝ ) , _ ⟩, ⟨ - ( Real.sqrt ( q3 j ) : ℝ ), _ ⟩ }, _ ⟩ <;> norm_num;
