      · rw [ show x = Complex.I by simpa [ Complex.ext_iff ] using ‹x.re = 0 ∧ x.im = 1› ] ; exact ⟨ Polynomial.X ^ 2 + 1, by exact Polynomial.monic_X_pow_add_C _ two_ne_zero, by norm_num ⟩ ;
